#!/usr/bin/env python3
"""Exact certificate for the chordal transverse divisor.

The six-coordinate model is the augmentation representation of
PSL(2,F_5) on P^1(F_5).  We work over Q(zeta_5), choose a C_5-eigenline on
the chordal singular quartic, and compute its A_5-orbit Z.

The certificate proves:

* the selected parameter has t^2 = 9/5;
* Z has twelve distinct points, all singular on F_t=P+tQ and all in Q=0;
* quadrics through Z have dimension six, hence equal the quadratic ideal of
  the rational normal quartic C=Sing(F_t);
* the degree-three part generated by those quadrics has dimension 22, and Q
  is not in it.

Thus Q|_C is a nonzero section of O_C(3)=O_P1(12) vanishing at the twelve
distinct points of Z.  Its zero divisor is exactly Z and is reduced.
"""

from __future__ import annotations

import argparse
from itertools import combinations
from pathlib import Path

from sympy import CRootOf, Poly, QQ, symbols


def act(mat, point):
    a, b, c, d = mat
    if point == 5:
        num, den = a, c
    else:
        num = (a * point + b) % 5
        den = (c * point + d) % 5
    if den % 5 == 0:
        return 5
    return (num * pow(den, 3, 5)) % 5


def perm(mat):
    return tuple(act(mat, point) for point in range(6))


def compose(left, right):
    return tuple(left[right[index]] for index in range(6))


def a5_on_six_points():
    generators = [perm((1, 1, 0, 1)), perm((0, 4, 1, 0))]
    identity = tuple(range(6))
    group = {identity}
    frontier = [identity]
    while frontier:
        element = frontier.pop()
        for generator in generators:
            product = compose(generator, element)
            if product not in group:
                group.add(product)
                frontier.append(product)
    return sorted(group)


def triple_orbits(group):
    unseen = {tuple(triple) for triple in combinations(range(6), 3)}
    orbits = []
    while unseen:
        seed = min(unseen)
        orbit = {
            tuple(sorted(element[index] for index in seed))
            for element in group
        }
        unseen.difference_update(orbit)
        orbits.append(sorted(orbit))
    return sorted(orbits)


def projective_normalize(point, zero):
    pivot = next(coordinate for coordinate in point if coordinate != zero)
    return tuple(coordinate / pivot for coordinate in point)


def field_sum(field, terms):
    result = field.zero
    for term in terms:
        result += term
    return result


def power_sum_three(field, point):
    return field_sum(field, (coordinate**3 for coordinate in point))


def triple_sum(field, point, triples):
    return field_sum(
        field,
        (point[i] * point[j] * point[k] for i, j, k in triples),
    )


def q_value(field, point, positive, all_triples):
    return (
        2 * triple_sum(field, point, positive)
        - triple_sum(field, point, all_triples)
    )


def q_derivative(field, point, index, positive, all_triples):
    def other_product(triple):
        other = [entry for entry in triple if entry != index]
        return point[other[0]] * point[other[1]]

    return (
        2
        * field_sum(
            field,
            (other_product(triple) for triple in positive if index in triple),
        )
        - field_sum(
            field,
            (other_product(triple) for triple in all_triples if index in triple),
        )
    )


def compositions(total, length):
    if length == 1:
        return [(total,)]
    output = []
    for first in range(total + 1):
        for tail in compositions(total - first, length - 1):
            output.append((first,) + tail)
    return output


def evaluate_monomial(field, point, exponent):
    value = field.one
    for coordinate, power in zip(point, exponent):
        value *= coordinate**power
    return value


def rref(field, rows):
    matrix = [list(row) for row in rows]
    if not matrix:
        return matrix, []
    row_count = len(matrix)
    column_count = len(matrix[0])
    pivots = []
    pivot_row = 0
    for column in range(column_count):
        choice = next(
            (row for row in range(pivot_row, row_count) if matrix[row][column]),
            None,
        )
        if choice is None:
            continue
        matrix[pivot_row], matrix[choice] = matrix[choice], matrix[pivot_row]
        inverse = field.one / matrix[pivot_row][column]
        matrix[pivot_row] = [entry * inverse for entry in matrix[pivot_row]]
        for row in range(row_count):
            if row == pivot_row or not matrix[row][column]:
                continue
            factor = matrix[row][column]
            matrix[row] = [
                entry - factor * pivot
                for entry, pivot in zip(matrix[row], matrix[pivot_row])
            ]
        pivots.append(column)
        pivot_row += 1
        if pivot_row == row_count:
            break
    return matrix, pivots


def matrix_rank(field, rows):
    return len(rref(field, rows)[1])


def nullspace(field, rows):
    reduced, pivots = rref(field, rows)
    column_count = len(rows[0])
    free = [column for column in range(column_count) if column not in pivots]
    basis = []
    for free_column in free:
        vector = [field.zero] * column_count
        vector[free_column] = field.one
        for row, pivot_column in enumerate(pivots):
            vector[pivot_column] = -reduced[row][free_column]
        basis.append(vector)
    return basis


def polynomial_add(field, left, right):
    result = dict(left)
    for exponent, coefficient in right.items():
        result[exponent] = result.get(exponent, field.zero) + coefficient
        if not result[exponent]:
            del result[exponent]
    return result


def polynomial_scale(field, scalar, polynomial):
    if not scalar:
        return {}
    return {
        exponent: scalar * coefficient
        for exponent, coefficient in polynomial.items()
        if scalar * coefficient
    }


def polynomial_multiply(field, left, right):
    result = {}
    for left_exp, left_coeff in left.items():
        for right_exp, right_coeff in right.items():
            exponent = tuple(a + b for a, b in zip(left_exp, right_exp))
            result[exponent] = (
                result.get(exponent, field.zero) + left_coeff * right_coeff
            )
            if not result[exponent]:
                del result[exponent]
    return result


def polynomial_product(field, factors):
    one_exp = (0, 0, 0, 0, 0)
    result = {one_exp: field.one}
    for factor in factors:
        result = polynomial_multiply(field, result, factor)
    return result


def coordinate_polynomials(field):
    variables = []
    for index in range(5):
        exponent = [0] * 5
        exponent[index] = 1
        variables.append({tuple(exponent): field.one})
    dependent = {}
    for variable in variables:
        dependent = polynomial_add(
            field, dependent, polynomial_scale(field, -field.one, variable)
        )
    return variables + [dependent]


def q_polynomial(field, positive, all_triples):
    coordinates = coordinate_polynomials(field)

    def sum_triples(triples):
        result = {}
        for triple in triples:
            term = polynomial_product(
                field, (coordinates[index] for index in triple)
            )
            result = polynomial_add(field, result, term)
        return result

    return polynomial_add(
        field,
        polynomial_scale(field, field.convert(2), sum_triples(positive)),
        polynomial_scale(field, -field.one, sum_triples(all_triples)),
    )


def vector_from_polynomial(field, polynomial, monomials):
    return [polynomial.get(exponent, field.zero) for exponent in monomials]


def report_lines():
    cyclotomic_variable = symbols("zeta")
    cyclotomic_polynomial = Poly(
        cyclotomic_variable**4
        + cyclotomic_variable**3
        + cyclotomic_variable**2
        + cyclotomic_variable
        + 1,
        cyclotomic_variable,
        domain=QQ,
    )
    zeta = CRootOf(cyclotomic_polynomial.as_expr(), 0)
    field = QQ.algebraic_field(zeta)
    root = field.unit

    group = a5_on_six_points()
    orbits = triple_orbits(group)
    assert len(group) == 60
    assert [len(orbit) for orbit in orbits] == [10, 10]
    positive = orbits[0]
    all_triples = list(combinations(range(6), 3))

    base_point = tuple([root**index for index in range(5)] + [field.zero])
    parameter = (
        -field.convert(QQ(3, 5))
        - field.convert(QQ(6, 5)) * (root**2 + root**3)
    )
    assert parameter**2 == field.convert(QQ(9, 5))

    orbit = {
        projective_normalize(
            tuple(base_point[element[index]] for index in range(6)), field.zero
        )
        for element in group
    }
    assert len(orbit) == 12

    for point in orbit:
        assert field_sum(field, point) == field.zero
        p_value = power_sum_three(field, point)
        q_at_point = q_value(field, point, positive, all_triples)
        assert p_value + parameter * q_at_point == field.zero
        assert q_at_point == field.zero
        derivatives = [
            field.convert(3) * point[index] ** 2
            + parameter
            * q_derivative(field, point, index, positive, all_triples)
            for index in range(6)
        ]
        assert all(
            derivatives[index] - derivatives[5] == field.zero
            for index in range(5)
        )

    degree_two = compositions(2, 5)
    evaluation = [
        [
            evaluate_monomial(field, point[:5], exponent)
            for exponent in degree_two
        ]
        for point in sorted(orbit, key=str)
    ]
    evaluation_rank = matrix_rank(field, evaluation)
    quadratic_ideal = nullspace(field, evaluation)
    assert evaluation_rank == 9
    assert len(quadratic_ideal) == 6

    degree_three = compositions(3, 5)
    degree_three_index = {
        exponent: index for index, exponent in enumerate(degree_three)
    }
    generated_cubics = []
    for quadric in quadratic_ideal:
        for variable_index in range(5):
            vector = [field.zero] * len(degree_three)
            for coefficient, exponent in zip(quadric, degree_two):
                target = list(exponent)
                target[variable_index] += 1
                vector[degree_three_index[tuple(target)]] += coefficient
            generated_cubics.append(vector)

    cubic_ideal_rank = matrix_rank(field, generated_cubics)
    assert cubic_ideal_rank == 22

    q_vector = vector_from_polynomial(
        field,
        q_polynomial(field, positive, all_triples),
        degree_three,
    )
    augmented_rank = matrix_rank(field, generated_cubics + [q_vector])
    assert augmented_rank == 23

    return [
        "A5 order: 60; triple orbit sizes: 10,10",
        "chosen C5 eigenline: t^2=9/5",
        "projective A5 orbit size: 12",
        "orbit checks: sum-zero, singular on F_t, and Q=0: PASS",
        "degree-2 evaluation rank on orbit: 9",
        "quadrics through orbit: dimension 6",
        "degree-3 ideal generated by those quadrics: dimension 22",
        "adjoining Q raises degree-3 rank to 23",
        "conclusion: Q|C is nonzero with reduced degree-12 zero divisor",
        "PASS",
    ]


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", type=Path)
    args = parser.parse_args()
    report = "\n".join(report_lines()) + "\n"
    if args.check is None:
        print(report, end="")
        return
    expected = args.check.read_text()
    if report != expected:
        raise SystemExit(
            "chordal transversality output mismatch\n"
            f"--- expected ---\n{expected}--- actual ---\n{report}"
        )
    print(report, end="")


if __name__ == "__main__":
    main()
